const headers = $input.item.json.headers;
const setCookieHeader = headers['set-cookie'];

let token = '';

if (Array.isArray(setCookieHeader)) {
  const match = setCookieHeader.find(c => c.startsWith('access_token_painel='));
  if (match) {
    token = match.split('access_token_painel=')[1].split(';')[0];
  }
} else if (typeof setCookieHeader === 'string' && setCookieHeader.includes('access_token_painel=')) {
  token = setCookieHeader.split('access_token_painel=')[1].split(';')[0];
}

if (!token) {
  throw new Error('Token nao encontrado no cookie de resposta do login');
}

return [{ json: { token } }];

const token = $input.first().json.token;
const url = 'https://api.cashbarber.com.br/api/painel/dashboard/getClientesPagamentoIncompleto';
const headers = {
  'Authorization': `Bearer ${token}`,
  'x-context': 'painel',
  'Content-Type': 'application/json;charset=UTF-8',
  'Accept': 'application/json'
};

function toE164(phone) {
  if (!phone) return '';
  let c = phone.toString().replace(/[^\d]/g, '');
  if (c.startsWith('55') && c.length >= 12) c = c.slice(2);
  const ddd = c.slice(0, 2);
  let num = c.slice(2);
  if (num.length === 8) num = '9' + num;
  return '55' + ddd + num;
}

const clientes = [];
let page = 1, total = Infinity;
while (clientes.length < total) {
  const r = await this.helpers.httpRequest({ method: 'POST', url, headers, body: { page }, json: true });
  total = r.total ?? 0;
  const lote = r.clientes || [];
  if (!lote.length) break;
  for (const c of lote) {
    clientes.push({
      id_cliente: c.clp_id_cliente,
      clp_id: c.id,
      nome: c.cliente?.cli_name || '',
      telefone_raw: c.cliente?.cli_telefone || '',
      telefone: toE164(c.cliente?.cli_telefone),
      plano: c.plano?.pla_nome || ''
    });
  }
  page++;
  if (page > 50) break;
}

return [{ json: { total: clientes.length, clientes } }];

const clientes = ($input.first().json.clientes || []).filter(c => c.telefone);
const j = JSON.stringify(clientes).replace(/'/g, "''");

const cols = "x(id_cliente bigint, clp_id bigint, nome text, telefone_raw text, telefone text, plano text)";

const leadsSql = `
INSERT INTO lead (lead_name, lead_telefone, mensalista, cliente_novo, update_at)
SELECT x.nome, x.telefone, true, true, now()
FROM jsonb_to_recordset('${j}'::jsonb) AS ${cols}
WHERE x.telefone <> ''
  AND NOT EXISTS (SELECT 1 FROM lead l WHERE l.lead_telefone = x.telefone);`;

const upsertSql = `
INSERT INTO pagamento_incompleto
  (id_cliente_cashbarber, clp_id, lead_id, nome, telefone_e164, plano, status, primeira_deteccao, ultima_deteccao)
SELECT x.id_cliente, x.clp_id,
       (SELECT id FROM lead l WHERE l.lead_telefone = x.telefone ORDER BY created_at LIMIT 1),
       x.nome, x.telefone, x.plano, 'atrasado', now(), now()
FROM jsonb_to_recordset('${j}'::jsonb) AS ${cols}
ON CONFLICT (id_cliente_cashbarber) DO UPDATE SET
  clp_id        = EXCLUDED.clp_id,
  lead_id       = COALESCE(EXCLUDED.lead_id, pagamento_incompleto.lead_id),
  nome          = EXCLUDED.nome,
  telefone_e164 = EXCLUDED.telefone_e164,
  plano         = EXCLUDED.plano,
  status        = 'atrasado',
  total_notificacoes = CASE WHEN pagamento_incompleto.status = 'resolvido' THEN 0 ELSE pagamento_incompleto.total_notificacoes END,
  ultima_notificacao_em = CASE WHEN pagamento_incompleto.status = 'resolvido' THEN NULL ELSE pagamento_incompleto.ultima_notificacao_em END,
  ultima_deteccao = now();`;

const resolvidosSql = `
UPDATE pagamento_incompleto
SET status = 'resolvido'
WHERE status = 'atrasado'
  AND ultima_deteccao < date_trunc('day', now());`;

const batchSql = [leadsSql, upsertSql, resolvidosSql].join('\n');
return [{ json: { batchSql } }];

const d = $('Selecionar Elegiveis').item.json;
const esc = s => (s == null ? '' : s.toString()).replace(/'/g, "''");
const pid = `'${esc(d.pagamento_id)}'::uuid`;
const tel = esc(d.telefone_e164);
const leadId = d.lead_id ? `'${esc(d.lead_id)}'::uuid` : 'NULL';

const sql =
`UPDATE pagamento_incompleto
   SET ultima_notificacao_em = now(), total_notificacoes = total_notificacoes + 1
 WHERE telefone_e164 = '${tel}';
INSERT INTO pagamento_incompleto_notificacoes
  (pagamento_id, lead_id, nome, telefone_e164, motivo, enviado_em)
VALUES (${pid}, ${leadId}, '${esc(d.lead_name || d.nome)}', '${esc(d.lead_telefone || d.telefone_e164)}', '${esc(d.msg_cliente)}', now());`;

return [{ json: { sql } }];

const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const norm = s => (s == null ? '' : s.toString()).replace(/\s+/g, ' ').trim();

const linhas = rows.map((d, idx) => {
  const nome  = norm(d.lead_name || d.nome) || 'Cliente';
  const tel   = norm(d.lead_telefone || d.telefone_e164);
  const plano = norm(d.plano);
  return `${idx + 1}. ${nome} — ${tel}${plano ? ' (' + plano + ')' : ''}`;
}).join('\n');

const text =
`📋 *COBRANÇAS ENVIADAS HOJE (${rows.length})*

Clientes avisados sobre pagamento pendente:

${linhas}`;

return [{ json: { text, qtd: rows.length } }];
